-- =============================================================================
-- SCRIPT DE RESTAURACIÓN DE VACANTES ELIMINADAS
-- =============================================================================
-- Restaura las 38 vacantes eliminadas por el script correcciones_convocatoria.sql
-- Las aplicaciones NO fueron eliminadas (175 aplicaciones huérfanas encontradas)
-- =============================================================================

START TRANSACTION;
SET FOREIGN_KEY_CHECKS = 0;

-- Restaurar las vacantes eliminadas

SET FOREIGN_KEY_CHECKS = 1;

-- Verificar restauración
SELECT id, code, location FROM kjrt_local_jobboard_vacancy 
WHERE id IN (749,750,757,758,759,760,793,794,815,816,818,819,919,920,921,922,923,925,926,961,962,963,964,967,968,1011,1012,1013,1014,1017,1018,1049,1050,1051,1052,1053,1055,1056);

COMMIT;
